<?phpnamespace App\Http\Controllers\Admin;use Core\App;use Core\Database;use App\Http\Middleware\Auth;class UsersController {    public function index() {        $db = App::resolve(Database::class);        $currentUser = Auth::authenticate();        $current_user_id = $currentUser['id'] ?? null;        if(!$current_user_id) {            http_response_code(404);            echo json_encode(["error" => "Admin not found"]);            exit;        }        $users = $db->query("            SELECT id,                    first_name,                    last_name,                    email,                    phone,                    role,                    department,                    is_active,                    hired_date             FROM users            WHERE role != 'admin'        ")->all();        $search = $_GET['search'] ?? "";        $status = $_GET['status'] ?? "";        $department = $_GET['department'] ?? "";        $role = $_GET['role'] ?? "";        $base_query = "                SELECT id,                    first_name,                     last_name,                     email,                     phone,                     role,                     department,                     is_active                FROM users                 WHERE 1=1         ";        $params = [];        if(!empty($search)) {            $base_query .= " AND (first_name LIKE :search OR last_name LIKE :search OR email LIKE :search) ";            $params['search'] = "%$search%";        }        if(!empty($status)) {            $base_query .= " AND is_active = :status ";            $params['status'] = $status;        }        if(!empty($department)) {            $base_query .= " AND department = :department ";            $params['department'] = $department;        }        if(!empty($role)) {            $base_query .= " AND role = :role ";            $params['role'] = $role;        }        $filteredUsers = $db->query($base_query, $params)->all();        if(!$filteredUsers) {            http_response_code(404);            echo json_encode(["error" => "No users found"]);            exit;        }        http_response_code(200);        echo json_encode([             'success' => true,             'message' => 'Employee List fetched successfully',             'id' => $current_user_id,             'users' => $users,             'search' => $search,             'filtered_users' => $filteredUsers         ]);    }    public function show($id) {        $db = App::resolve(Database::class);        $currentUser = Auth::authenticate();        $current_user_id = $currentUser['id'] ?? null;        if(!$current_user_id) {            http_response_code(404);            echo json_encode(["error" => "Admin not found"]);            exit;        }        $user = $db->query("            SELECT id,                    first_name,                    last_name,                    email,                    phone,                    role,                    assigned_to as manager_id,                   department,                    is_active,                    hired_date,                   salary                    FROM users            WHERE id = :id        ", [            'id' => $id        ])->find();        if (!$user) {            http_response_code(404);            echo json_encode(["error" => "User not found"]);            exit;        }        // select all possible managers        $managers = $db->query("        SELECT id, CONCAT(first_name, ' ', last_name) as name         FROM users         WHERE role = 'manager' AND is_active = 1        ")->all();////        $userDetails = [//            'id' => $user['id'],//            'first_name' => $user['first_name'],//            'last_name' => $user['last_name'],//            'email' => $user['email'],//            'phone' => $user['phone'],//            'role' => $user['role'],//            'manager_id' => $user['manager_id'],//            'department' => $user['department'],//            'is_active' => $user['is_active'],//            'hired_date' => $user['hired_date'],//            'salary' => $user['salary'],//            'managers' => $managers//        ];        if(!$managers) {            http_response_code(404);            echo json_encode(["error" => "Manager not found"]);            exit;        }        http_response_code(200);        echo json_encode([            'success' => true,            'message' => 'Existing user details fetched successfully',            'id' => $id,            'user' => $user        ]);    }    public function patch($id) {        $db = App::resolve(Database::class);        $currentUser = Auth::authenticate();        $current_user_id = $currentUser['id'] ?? null;        $existingUser = $db->query("SELECT * FROM users WHERE id = :id", [            'id' => $id        ])->find();        if (!$existingUser) {            http_response_code(404);            echo json_encode(["error" => "User to edit not found"]);            exit;        }        if(!$current_user_id) {            http_response_code(404);            echo json_encode(["error" => "Admin not found"]);            exit;        }        $input = json_decode(file_get_contents('php://input'), true);        $first_name = array_key_exists('first_name', $input) ? $input['first_name'] : $existingUser['first_name'];        $last_name  = array_key_exists('last_name', $input)  ? $input['last_name']  : $existingUser['last_name'];        $email      = array_key_exists('email', $input)      ? $input['email']      : $existingUser['email'];        $phone      = array_key_exists('phone', $input)      ? $input['phone']      : $existingUser['phone'];        $role       = array_key_exists('role', $input)       ? $input['role']       : $existingUser['role'];        $department = array_key_exists('department', $input) ? $input['department'] : $existingUser['department'];        $salary     = array_key_exists('salary', $input)     ? $input['salary']     : $existingUser['salary'];        $hired_date = array_key_exists('hired_date', $input) ? $input['hired_date'] : $existingUser['hired_date'];        $is_active  = array_key_exists('is_active', $input)            ? (int)$input['is_active']            : (int)$existingUser['is_active'];        $manager_id = array_key_exists('manager_id', $input)            ? (!empty($input['manager_id']) ? (int)$input['manager_id'] : null)            : $existingUser['manager_id'];        $db->query("        UPDATE users         SET first_name = :first_name,             last_name = :last_name,             email = :email,             phone = :phone,             role = :role,             department = :department,             assigned_to = :assigned_to,            is_active = :is_active,             hired_date = :hired_date,             salary = :salary         WHERE id = :id        ", [            'id'          => $id,            'first_name'  => $first_name,            'last_name'   => $last_name,            'email'       => $email,            'phone'       => $phone,            'role'        => $role,            'department'  => $department,            'assigned_to'  => $manager_id,            'is_active'   => $is_active,            'hired_date' => empty($hired_date) ? null : $hired_date,            'salary'      => empty($salary) ? null : $salary        ]);        $editedUser = $db->query("        SELECT id, first_name, last_name, email, phone, role, department, assigned_to, is_active, hired_date, salary         FROM users         WHERE id = :id        ", ['id' => $id])->find();        if(!$editedUser) {            http_response_code(500);            echo json_encode(['error' => 'Failed to update user']);            exit;        }        http_response_code(200);        echo json_encode([            'success' => true,            'message' => 'User profile updated successfully',            'user'    => $editedUser        ]);    }    public function destroy($id) {        $db = App::resolve(Database::class);        $currentUser = Auth::authenticate();        $current_user_id = $currentUser['id'] ?? null;        if(!$current_user_id) {            http_response_code(404);            echo json_encode(["error" => "Admin not found"]);            exit;        }        $deleteUser = $db->query("UPDATE users SET is_active = 0 WHERE id = :id", [            'id' => $id        ]);        http_response_code(200);        echo json_encode([            'success' => true,            'message' => 'User deleted successfully',            'id' => $id,            'deleted' => $deleteUser        ]);    }    public function profile($id) {        $db = App::resolve(Database::class);        $currentUser = Auth::authenticate();        $current_user_id = $currentUser['id'] ?? null;        if(!$current_user_id) {            http_response_code(404);            echo json_encode(["error" => "Admin not found"]);            exit;        }        $user = $db->query("             SELECT u.id,                 u.first_name,                  u.last_name,                 u.email,                   u.phone,                 u.role,                  u.assigned_to,                 u.department,                 u.salary,                 u.hired_date,                 u.is_active,                 lt.name as leave_type_name,                 lb.remaining_balance as remaining_balance            FROM users u             LEFT JOIN leave_balance lb ON lb.user_id = u.id            LEFT JOIN leave_types lt ON lb.leave_type_id = lt.id            WHERE u.id = :id        ", [            'id' => $id        ])->all();        if(!$user) {            http_response_code(404);            echo json_encode(["error" => "User not found"]);            exit;        }        $structuredData = [            'id' => $user[0]['id'],            'first_name' => $user[0]['first_name'],            'last_name' => $user[0]['last_name'],            'email' => $user[0]['email'],            'phone' => $user[0]['phone'],            'role' => $user[0]['role'],            'department' => $user[0]['department'],            'is_active' => $user[0]['is_active'],            'hired_date' => $user[0]['hired_date'],            'salary' => $user[0]['salary'],            'leave_balance' => []        ];        foreach($user as $employee) {            if(!empty($employee['leave_type_name'])) {                $structuredData['leave_balance'][] = [                    'leave_type_name' => $employee['leave_type_name'],                    'remaining_balance' => $employee['remaining_balance'],                ];            }        }        http_response_code(200);        echo json_encode([            'success' => true,            'message' => 'Employee details fetched successfully',            'id' => $id,            'user' => $structuredData        ]);    }}